<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { onBeforeRouteLeave,useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { apiRequest,allOptions } from '../api/client'
import type { Archive,Page } from '../api/types'
import type { Employee,Grant,OrgUnit,Role } from '../api/people'
import { employeeStatuses,personnelTypes,eventKinds,orgKinds } from '../api/people'
import { useAccess } from '../access'
import GrantEditor from '../components/GrantEditor.vue'
import EmployeeProfile from '../components/EmployeeProfile.vue'
const route=useRoute(),router=useRouter(),access=useAccess()
const section=computed(()=>String(route.params.section)),title=computed(()=>({'org-units':'组织架构',positions:'岗位管理',employees:'员工档案',roles:'角色权限'}[section.value]||'人员架构'))
const path=computed(()=>`/people/${section.value}`),canManage=computed(()=>section.value==='roles'?access.admin.value:section.value==='positions'?access.hasGlobal('position.manage'):access.has(section.value==='employees'?'employee.manage':'org.manage'))
const keyword=ref(String(route.query.keyword||'')),status=ref(String(route.query.status||'')),orgFilter=ref<number|undefined>(Number(route.query.org_unit_id)||undefined),page=ref(Number(route.query.page)||1),pageSize=ref(Number(route.query.page_size)||20)
const rows=ref<Archive[]>([]),total=ref(0),loading=ref(false),error=ref(''),tree=ref<OrgUnit[]>([]),orgs=ref<OrgUnit[]>([]),positions=ref<Archive[]>([]),employees=ref<Employee[]>([]),roles=ref<Role[]>([]),stores=ref<Archive[]>([]),warehouses=ref<Archive[]>([])
const permissions=ref<{code:string;name:string;group:string}[]>([]),scopeTypes=ref<{code:string;name:string}[]>([])
let controller:AbortController|undefined,revision=0,timer:ReturnType<typeof setTimeout>|undefined;const composing=ref(false)
async function load(){const version=++revision;controller?.abort();controller=new AbortController();loading.value=true;error.value='';const query=new URLSearchParams({page:String(page.value),page_size:String(pageSize.value)});if(keyword.value)query.set('keyword',keyword.value);if(status.value)query.set('status',status.value);if(orgFilter.value&&section.value==='employees')query.set('org_unit_id',String(orgFilter.value));await router.replace({query:Object.fromEntries(query)});try{const result=await apiRequest<Page<Archive>>(`${path.value}?${query}`,{signal:controller.signal});if(version!==revision)return;rows.value=result.items;total.value=result.total;if(page.value>1&&!rows.value.length){page.value=Math.max(1,Math.ceil(total.value/pageSize.value));void load()}if(section.value==='org-units')tree.value=await apiRequest<OrgUnit[]>('/people/org-units/tree')}catch(e){if(version===revision&&(e as Error).name!=='AbortError')error.value=(e as Error).message}finally{if(version===revision)loading.value=false}}
async function options(){try{const tasks:Promise<unknown>[]=[];if(access.has('org.read'))tasks.push(allOptions<OrgUnit>('/people/org-units').then(v=>orgs.value=v));if(access.has('position.read'))tasks.push(allOptions<Archive>('/people/positions').then(v=>positions.value=v));if(access.has('employee.read'))tasks.push(allOptions<Employee & Archive>('/people/employees').then(v=>employees.value=v));if(access.admin.value){tasks.push(allOptions<Role>('/people/roles').then(v=>roles.value=v),allOptions<Archive>('/stores').then(v=>stores.value=v),allOptions<Archive>('/warehouses').then(v=>warehouses.value=v),apiRequest<{permissions:typeof permissions.value;scope_types:typeof scopeTypes.value}>('/people/permissions').then(v=>{permissions.value=v.permissions;scopeTypes.value=v.scope_types}))}await Promise.all(tasks)}catch(e){error.value=(e as Error).message}}
function search(){clearTimeout(timer);if(composing.value)return;timer=setTimeout(()=>{page.value=1;void load()},keyword.value?300:0)}
const dialog=ref(false),mode=ref<'record'|'event'|'account'|'grants'>('record'),record=ref<Archive|null>(null),form=ref<Record<string,any>>({}),initial=ref(''),busy=ref(false),formError=ref(''),detail=ref<Employee|null>(null),detailOpen=ref(false),detailLoading=ref(false),detailError=ref('');let detailRevision=0
const dialogTitle=computed(()=>mode.value==='event'?'办理人事异动':mode.value==='account'?'账号配置':mode.value==='grants'?'配置角色与范围':`${record.value?'编辑':'新建'}${title.value}`)
function openRecord(row:Archive|null){record.value=row;mode.value='record';form.value=row?JSON.parse(JSON.stringify(row)):section.value==='employees'?{code:'',name:'',phone:'',personnel_type:'EMPLOYEE',status:'PENDING',org_unit_id:null,position_id:null,manager_id:null,hire_date:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})}:section.value==='org-units'?{code:'',name:'',status:'ACTIVE',kind:'DEPARTMENT',parent_id:null,store_id:null,warehouse_id:null}:section.value==='roles'?{code:'',name:'',status:'ACTIVE',permissions:[]}:{code:'',name:'',status:'ACTIVE'};showForm()}
function showForm(){formError.value='';initial.value=JSON.stringify(form.value);dialog.value=true}
async function close(done?:()=>void){if(busy.value)return;if(JSON.stringify(form.value)!==initial.value){try{await ElMessageBox.confirm('内容尚未保存，关闭后将丢失。','放弃修改？',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}dialog.value=false;done?.()}
onBeforeRouteLeave(async()=>{if(dialog.value){await close();return !dialog.value}return true})
async function showDetail(id:number){const version=++detailRevision;detailOpen.value=true;detailLoading.value=true;detailError.value='';detail.value=null;try{const result=await apiRequest<Employee>(`/people/employees/${id}`);if(version===detailRevision)detail.value=result}catch(e){if(version===detailRevision)detailError.value=(e as Error).message}finally{if(version===detailRevision)detailLoading.value=false}}
watch(detailOpen,v=>{if(!v)detailRevision++})
function event(){if(!detail.value)return;record.value=detail.value as unknown as Archive;mode.value='event';form.value={kind:'TRANSFER',effective_date:new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),reason:'',org_unit_id:detail.value.org_unit_id,position_id:detail.value.position_id,manager_id:detail.value.manager_id||null,handover_employee_id:null,handover_notes:'',assign_grants:false,grants:[]};showForm()}
function account(){mode.value='account';form.value={username:detail.value?.account?.username||'',password:'',enabled:detail.value?.account?.enabled??false};showForm()}
function grantPayload(grants:Grant[]):Grant[]{return grants.map(g=>({role_id:g.role_id,scope_type:g.scope_type,scope_ids:[...g.scope_ids]}))}
function grants(){mode.value='grants';form.value={grants:grantPayload(detail.value?.account?.grants||[])};showForm()}
const canEvent=computed(()=>access.has('employee.manage')||access.has('employee.transfer')||access.has('employee.leave'))
const allowedEvents=computed(()=>eventKinds.filter(k=>k.value==='ONBOARD'?detail.value?.status==='PENDING'&&access.has('employee.manage'):k.value==='CONFIRM'?detail.value?.status==='PROBATION'&&access.has('employee.manage'):['PROBATION','ACTIVE'].includes(detail.value?.status||'')&&(k.value==='TRANSFER'?access.has('employee.transfer'):access.has('employee.leave'))))
watch(()=>form.value.kind,(kind)=>{formError.value='';if(section.value==='org-units'){if(kind!=='STORE')form.value.store_id=null;if(kind!=='WAREHOUSE')form.value.warehouse_id=null}})
function grantValid(grants:Grant[]){return grants.every(g=>g.role_id>0&&(!['ORG_TREE','STORES','WAREHOUSES'].includes(g.scope_type)||g.scope_ids.length>0))}
async function save(){if(busy.value)return;formError.value='';let endpoint=path.value+(record.value?`/${record.value.id}`:''),method=record.value?'PATCH':'POST';let body:Record<string,unknown>={};const f=form.value
if(mode.value==='record'){
 const employee=section.value==='employees';const keys=employee?(record.value?['name','phone','personnel_type']:['code','name','phone','personnel_type','status','org_unit_id','position_id','manager_id','hire_date']):section.value==='org-units'?['code','name','status','kind','parent_id',...(access.admin.value?['store_id','warehouse_id']:[])]:section.value==='roles'?['code','name','status','permissions']:['code','name','status'];body=Object.fromEntries(keys.map(k=>[k,f[k]===''&&['phone','hire_date'].includes(k)?null:f[k]]));if(!f.name||(!record.value&&!f.code)){formError.value='请填写编码和名称';return}if(employee&&!record.value&&(!f.org_unit_id||!f.position_id||!f.hire_date)){formError.value='请选择组织、岗位与入职日期';return}
}else if(mode.value==='event'){
 if(!f.effective_date||!f.reason?.trim()){formError.value='请填写生效日期与异动原因';return}if(!allowedEvents.value.some(k=>k.value===f.kind)){formError.value='没有办理此异动的权限';return}endpoint=`/people/employees/${detail.value!.id}/events`;method='POST';body={kind:f.kind,effective_date:f.effective_date,reason:f.reason,handover_employee_id:f.handover_employee_id,handover_notes:f.handover_notes};if(f.kind==='TRANSFER')Object.assign(body,{org_unit_id:f.org_unit_id,position_id:f.position_id,manager_id:f.manager_id});if(access.admin.value&&f.assign_grants){if(!grantValid(f.grants)){formError.value='请完整选择授权角色与范围对象';return}body.grants=grantPayload(f.grants)}
}else if(mode.value==='account'){
 if((!detail.value?.account||f.password)&&f.password.length<12){formError.value='密码至少需要12位';return}if(!detail.value?.account&&!f.username.trim()){formError.value='请填写用户名';return}endpoint=detail.value?.account?`/people/accounts/${detail.value.account.id}`:`/people/employees/${detail.value!.id}/account`;method=detail.value?.account?'PATCH':'POST';body={enabled:f.enabled,...(!detail.value?.account?{username:f.username}:{}),...(f.password?{password:f.password}:{})}
}else{if(!grantValid(f.grants)){formError.value='请完整选择授权角色与范围对象';return}endpoint=`/people/accounts/${detail.value!.account!.id}/grants`;method='PUT';body={grants:grantPayload(f.grants)}}
if(mode.value!=='record'||f.status==='INACTIVE'){try{await ElMessageBox.confirm(mode.value==='event'&&f.kind==='TRANSFER'?'调岗将退出该员工所有登录，并撤销全部旧授权。未配置新授权时仅能查看本人档案。':mode.value==='event'&&f.kind==='LEAVE'?'离职将立即停用账号并退出全部登录。':'确认保存此次变更？角色和账号变更会影响员工访问权限。','确认变更',{confirmButtonText:'确认保存',cancelButtonText:'取消',type:'warning'})}catch{return}}
busy.value=true;try{await apiRequest(endpoint,{method,body:JSON.stringify(body)});dialog.value=false;form.value={grants:[]};initial.value='';ElMessage.success('已保存');await Promise.all([load(),options()]);if(detailOpen.value&&detail.value)await showDetail(detail.value.id)}catch(e){formError.value=(e as Error).message}finally{busy.value=false}}
const statusOptions=computed(()=>section.value==='employees'?employeeStatuses:[{value:'ACTIVE',label:'启用'},{value:'INACTIVE',label:'停用'}])
watch([status,orgFilter],()=>{page.value=1;void load()});watch(keyword,search);onMounted(()=>{void load();void options()});onBeforeUnmount(()=>{revision++;detailRevision++;controller?.abort();clearTimeout(timer)})
</script>
<template><section><div class="page-heading"><div><h1>{{title}}</h1><p>维护人员任职与组织归属，历史记录持续保留。</p></div><el-button v-if="canManage" type="primary" @click="openRecord(null)">新建{{section==='employees'?'员工':section==='org-units'?'组织':section==='positions'?'岗位':'角色'}}</el-button></div>
<div v-if="section==='org-units'&&tree.length" class="panel editor-panel"><h2>组织树</h2><el-tree :data="tree" node-key="id" :props="{label:'name',children:'children'}" default-expand-all :expand-on-click-node="true"/></div>
<div class="panel"><div class="table-toolbar"><el-input v-model="keyword" aria-label="搜索编码或姓名" placeholder="搜索编码或姓名" @keyup.enter="page=1;load()" @compositionstart="composing=true" @compositionend="composing=false;search()"/><el-button v-if="keyword" text aria-label="清除搜索" @click="keyword=''">清除</el-button><el-select v-model="status" clearable aria-label="筛选状态" placeholder="全部状态"><el-option v-for="item in statusOptions" :key="item.value" :value="item.value" :label="item.label"/></el-select><el-select v-if="section==='employees'" v-model="orgFilter" clearable filterable aria-label="筛选组织" placeholder="全部组织"><el-option v-for="item in orgs" :key="item.id" :value="item.id" :label="item.name"/></el-select><el-button :loading="loading" @click="load">刷新</el-button></div><div v-if="error" class="inline-error" role="alert">{{error}} <el-button text @click="load();options()">重试</el-button></div><el-table v-else :data="rows" v-loading="loading" :empty-text="loading?'正在加载…':keyword||status?'没有匹配记录':'暂无记录'" row-key="id"><el-table-column prop="code" :label="section==='employees'?'工号':'编码'" min-width="140"/><el-table-column prop="name" :label="section==='employees'?'姓名':'名称'" min-width="160"/><template v-if="section==='employees'"><el-table-column prop="org_unit_name" label="组织" min-width="140"/><el-table-column prop="position_name" label="岗位" min-width="120"/></template><el-table-column label="状态" width="100"><template #default="{row}">{{statusOptions.find(item=>item.value===row.status)?.label||row.status}}</template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button v-if="section==='employees'" text type="primary" @click="showDetail(row.id)">查看</el-button><el-button v-if="canManage" text type="primary" @click="openRecord(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><span role="status">共 {{total}} 条记录</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[20,50,100]" layout="sizes,prev,pager,next" @current-change="load" @size-change="page=1;load()"/></div></div>
<el-dialog v-model="detailOpen" title="员工档案" width="960px" :close-on-click-modal="false"><div v-loading="detailLoading"><p v-if="detailError" role="alert" class="inline-error">{{detailError}}</p><template v-if="detail"><EmployeeProfile :employee="detail"/><template v-if="access.admin.value"><h2>登录账号</h2><p>{{detail.account?`${detail.account.username} · ${detail.account.enabled?'启用':'停用'}`:'尚未绑定账号'}}</p></template><div class="heading-actions"><el-button v-if="canEvent&&allowedEvents.length" @click="event();form.kind=allowedEvents[0]?.value">办理人事异动</el-button><el-button v-if="access.admin.value" @click="account">{{detail.account?'启停 / 重置密码':'绑定账号'}}</el-button><el-button v-if="access.admin.value&&detail.account" @click="grants">配置角色与范围</el-button></div></template></div></el-dialog>
<el-dialog :model-value="dialog" :title="dialogTitle" width="720px" :close-on-click-modal="false" :close-on-press-escape="!busy" :before-close="close" @update:model-value="dialog=$event"><el-form :model="form" label-position="top" novalidate :disabled="busy" @submit.prevent="save"><div class="form-grid">
<template v-if="mode==='record'"><el-form-item v-if="!record" label="编码 / 工号" for="people-code"><el-input id="people-code" v-model="form.code" maxlength="64"/></el-form-item><el-form-item label="名称 / 姓名" for="people-name"><el-input id="people-name" v-model="form.name" maxlength="128"/></el-form-item><el-form-item v-if="section!=='employees'||!record" label="状态"><el-select v-model="form.status" aria-label="档案状态"><el-option v-for="item in statusOptions.filter(s=>section!=='employees'||s.value!=='LEFT')" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item>
<template v-if="section==='employees'"><el-form-item label="联系电话" for="people-phone"><el-input id="people-phone" v-model="form.phone" maxlength="32"/></el-form-item><el-form-item label="人员类型"><el-select v-model="form.personnel_type" aria-label="人员类型"><el-option v-for="item in personnelTypes" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item></template>
<template v-if="section==='org-units'"><el-form-item label="组织类型"><el-select v-model="form.kind" aria-label="组织类型"><el-option v-for="item in orgKinds" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item label="上级组织"><el-select v-model="form.parent_id" clearable filterable aria-label="上级组织"><el-option v-for="item in orgs.filter(o=>o.id!==record?.id)" :key="item.id" :value="item.id" :label="item.name"/></el-select><span class="field-help">公司根节点不选上级组织</span></el-form-item><el-form-item v-if="access.admin.value&&form.kind==='STORE'" label="关联门店"><el-select v-model="form.store_id" clearable filterable aria-label="关联门店"><el-option v-for="item in stores" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><el-form-item v-if="access.admin.value&&form.kind==='WAREHOUSE'" label="关联仓库"><el-select v-model="form.warehouse_id" clearable filterable aria-label="关联仓库"><el-option v-for="item in warehouses" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item></template>
<el-form-item v-if="section==='roles'" class="span-full" label="角色权限"><el-checkbox-group v-model="form.permissions"><div v-for="group in [...new Set(permissions.map(p=>p.group))]" :key="group"><h3>{{group}}</h3><el-checkbox v-for="item in permissions.filter(p=>p.group===group)" :key="item.code" :value="item.code">{{item.name}}</el-checkbox></div></el-checkbox-group></el-form-item></template>
<template v-if="(mode==='record'&&section==='employees'&&!record)||(mode==='event'&&form.kind==='TRANSFER')"><el-form-item label="任职组织"><el-select v-model="form.org_unit_id" filterable aria-label="任职组织"><el-option v-for="item in orgs" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="岗位"><el-select v-model="form.position_id" filterable aria-label="岗位"><el-option v-for="item in positions" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="直属上级"><el-select v-model="form.manager_id" clearable filterable aria-label="直属上级"><el-option v-for="item in employees.filter(e=>e.id!==record?.id&&e.status!=='LEFT')" :key="item.id" :label="`${item.name} · ${item.code}`" :value="item.id"/></el-select></el-form-item></template>
<el-form-item v-if="mode==='record'&&section==='employees'&&!record" label="入职日期"><el-date-picker v-model="form.hire_date" type="date" value-format="YYYY-MM-DD" aria-label="入职日期"/></el-form-item>
<template v-if="mode==='event'"><el-form-item label="异动类型"><el-select v-model="form.kind" aria-label="异动类型"><el-option v-for="item in allowedEvents" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.effective_date" type="date" value-format="YYYY-MM-DD" aria-label="生效日期"/></el-form-item><el-form-item label="异动原因" class="span-full" for="event-reason"><el-input id="event-reason" v-model="form.reason" type="textarea" :rows="3" resize="none" maxlength="255"/></el-form-item><el-form-item label="交接人"><el-select v-model="form.handover_employee_id" clearable filterable aria-label="交接人"><el-option v-for="item in employees.filter(e=>e.id!==detail?.id&&e.status!=='LEFT')" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><el-form-item label="交接说明" for="event-handover"><el-input id="event-handover" v-model="form.handover_notes" type="textarea" :rows="3" resize="none" maxlength="2000"/></el-form-item><el-alert v-if="form.kind==='TRANSFER'" class="span-full" type="warning" :closable="false" title="调岗会退出全部登录并撤销原授权；未配置新授权时仅能查看本人档案。"/><el-checkbox v-if="access.admin.value&&form.kind==='TRANSFER'" v-model="form.assign_grants">调岗同时配置新授权</el-checkbox></template>
<template v-if="mode==='account'"><el-form-item label="用户名" for="account-username"><el-input id="account-username" v-model="form.username" :disabled="!!detail?.account" autocomplete="off"/></el-form-item><el-form-item :label="detail?.account?'新密码（留空不修改）':'初始密码（至少12位）'" for="account-password"><el-input id="account-password" v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="启用账号"><el-switch v-model="form.enabled" :disabled="!['ACTIVE','PROBATION'].includes(detail?.status||'')"/><span class="field-help">仅试用或在职员工可启用</span></el-form-item></template>
<GrantEditor v-if="mode==='grants'||(mode==='event'&&form.assign_grants&&access.admin.value)" v-model="form.grants" class="span-full" :roles="roles" :scope-types="scopeTypes" :orgs="orgs" :stores="stores" :warehouses="warehouses"/></div><p v-if="formError" class="inline-error" role="alert">{{formError}}</p></el-form><template #footer><el-button :disabled="busy" @click="close()">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></template></el-dialog>
</section></template>
